import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    while True:
        try:
            record = next(reader)
        except StopIteration:
            break
        except csv.Error:
            continue
        if record:
            records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].removeprefix("\ufeff")

    data = records[1:]
    width = max([len(columns)] + [len(row) for row in data])

    while len(columns) < width:
        index = len(columns) - len(records[0]) + 1
        name = f"extra_{index}"
        while name in columns:
            index += 1
            name = f"extra_{index}"
        columns.append(name)

    rows = [row + [""] * (width - len(row)) for row in data]
    return {"columns": columns, "rows": rows}
